def sites_list(workspace_id=None, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0097000" if __import__("os").path.isdir("./environment_mix/0097000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "sites_list"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_id=None, workspace_id_used=None, site_id_used=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"wf_req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "ts": _now(),
            "endpoint": endpoint,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": credential_id,
            "workspace_id": workspace_id_used,
            "site_id": site_id_used
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    def _decode_cursor(c):
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            return obj
        except Exception:
            return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Ambient auth: find any workspace we can act within; if filter provided, must be reachable.
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    sites = _load("sites.json")
    if not isinstance(sites, list):
        sites = []

    # Validate inputs
    if workspace_id is not None and not isinstance(workspace_id, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id must be a string")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "disabled", "archived"):
            _log("VALIDATION_ERROR", workspace_id_used=workspace_id)
            return _err("VALIDATION_ERROR", "Invalid status")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")
    if cursor is not None and not isinstance(cursor, str):
        _log("VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in ("created_at", "updated_at", "name", "last_published_at"):
        _log("VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "Invalid sort field")
    if order is None:
        order = "asc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        _log("VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "Invalid order")

    # Determine authorized workspaces (ambient). If we have a workspaces collection, use it; else infer from sites.
    ws_ids = set()
    for w in workspaces:
        if isinstance(w, dict) and isinstance(w.get("id"), str):
            ws_ids.add(w["id"])
    if not ws_ids:
        for s in sites:
            if isinstance(s, dict) and isinstance(s.get("workspace_id"), str):
                ws_ids.add(s["workspace_id"])

    if workspace_id is not None:
        if workspace_id not in ws_ids:
            _log("UNAUTHORIZED", workspace_id_used=workspace_id)
            return _err("UNAUTHORIZED", "Caller is not authorized for the requested workspace")
        authorized_ws = {workspace_id}
    else:
        if not ws_ids:
            _log("UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No authorized workspace context available")
        authorized_ws = ws_ids

    # Base filter: visible sites and not archived by default rule.
    filtered = []
    for s in sites:
        if not isinstance(s, dict):
            continue
        if s.get("workspace_id") not in authorized_ws:
            continue
        if s.get("status") == "archived":
            continue
        if status is not None and s.get("status") != status:
            continue
        if workspace_id is not None and s.get("workspace_id") != workspace_id:
            continue
        filtered.append(s)

    # Sort
    def _parse_dt(x):
        if x is None:
            return None
        if isinstance(x, str):
            # tolerate ISO-like strings
            try:
                if x.endswith("Z"):
                    x2 = x[:-1]
                    return datetime.datetime.fromisoformat(x2)
                return datetime.datetime.fromisoformat(x)
            except Exception:
                return None
        return None

    def _key(s):
        v = s.get(sort)
        if sort in ("created_at", "updated_at", "last_published_at"):
            dt = _parse_dt(v)
            # None sorts last for asc, first for desc via tuple
            return (dt is None, dt or datetime.datetime.min)
        if sort == "name":
            return (v is None, str(v).lower() if isinstance(v, str) else str(v))
        return (v is None, v)

    rev = (order == "desc")
    try:
        filtered.sort(key=_key, reverse=rev)
    except Exception:
        _log("VALIDATION_ERROR", workspace_id_used=workspace_id)
        return _err("VALIDATION_ERROR", "Unable to sort with provided parameters")

    # Cursor pagination: cursor carries {"offset": int}
    offset = 0
    if cursor:
        cobj = _decode_cursor(cursor)
        if not cobj or "offset" not in cobj or not isinstance(cobj["offset"], int) or cobj["offset"] < 0:
            _log("VALIDATION_ERROR", workspace_id_used=workspace_id)
            return _err("VALIDATION_ERROR", "Invalid cursor")
        offset = cobj["offset"]

    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor({"offset": next_offset}) if has_more else None

    _log("OK", workspace_id_used=workspace_id)
    return {
        "sites": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def sites_get(site_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0097000" if __import__("os").path.isdir("./environment_mix/0097000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "sites_get"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_id=None, workspace_id_used=None, site_id_used=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"wf_req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "ts": _now(),
            "endpoint": endpoint,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": credential_id,
            "workspace_id": workspace_id_used,
            "site_id": site_id_used
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(site_id, str) or not re.match(r"^wf_site_[0-9A-Z]{18,}$", site_id):
        _log("VALIDATION_ERROR", site_id_used=site_id if isinstance(site_id, str) else None)
        return _err("VALIDATION_ERROR", "site_id is invalid")

    sites = _load("sites.json")
    if not isinstance(sites, list):
        sites = []

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws_ids = set()
    for w in workspaces:
        if isinstance(w, dict) and isinstance(w.get("id"), str):
            ws_ids.add(w["id"])
    if not ws_ids:
        for s in sites:
            if isinstance(s, dict) and isinstance(s.get("workspace_id"), str):
                ws_ids.add(s["workspace_id"])

    site = None
    for s in sites:
        if isinstance(s, dict) and s.get("id") == site_id:
            site = s
            break
    if site is None:
        _log("NOT_FOUND", site_id_used=site_id)
        return _err("NOT_FOUND", "Site not found")

    # Tenant isolation: must be within any authorized workspace context.
    if site.get("workspace_id") not in ws_ids:
        _log("UNAUTHORIZED", site_id_used=site_id, workspace_id_used=site.get("workspace_id"))
        return _err("UNAUTHORIZED", "Caller is not authorized to view this site")

    # Return site row (includes publish metadata).
    _log("OK", site_id_used=site_id, workspace_id_used=site.get("workspace_id"))
    return {"site": site}

def sites_publish(site_id, publish_mode, domains=None, requested_by=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0097000" if __import__("os").path.isdir("./environment_mix/0097000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "sites_publish"

    def _now_dt():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _now():
        return _now_dt().isoformat() + "Z"

    def _log(status_code, credential_id=None, workspace_id_used=None, site_id_used=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"wf_req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "ts": _now(),
            "endpoint": endpoint,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": credential_id,
            "workspace_id": workspace_id_used,
            "site_id": site_id_used
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(site_id, str) or not re.match(r"^wf_site_[0-9A-Z]{18,}$", site_id):
        _log("VALIDATION_ERROR", site_id_used=site_id if isinstance(site_id, str) else None)
        return _err("VALIDATION_ERROR", "site_id is invalid")
    if not isinstance(publish_mode, str) or publish_mode not in ("live", "staging"):
        _log("VALIDATION_ERROR", site_id_used=site_id)
        return _err("VALIDATION_ERROR", "publish_mode is invalid")
    if domains is not None:
        if not isinstance(domains, list) or any((not isinstance(x, str) or not x.strip()) for x in domains):
            _log("VALIDATION_ERROR", site_id_used=site_id)
            return _err("VALIDATION_ERROR", "domains must be an array of non-empty strings")
    if requested_by is not None and not isinstance(requested_by, str):
        _log("VALIDATION_ERROR", site_id_used=site_id)
        return _err("VALIDATION_ERROR", "requested_by must be a string")

    sites = _load("sites.json")
    if not isinstance(sites, list):
        sites = []
    publish_events = _load("publish_events.json")
    if not isinstance(publish_events, list):
        publish_events = []

    # Ambient auth: authorize if site.workspace_id appears in known workspaces or inferred from sites.
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws_ids = set()
    for w in workspaces:
        if isinstance(w, dict) and isinstance(w.get("id"), str):
            ws_ids.add(w["id"])
    if not ws_ids:
        for s in sites:
            if isinstance(s, dict) and isinstance(s.get("workspace_id"), str):
                ws_ids.add(s["workspace_id"])

    site_idx = None
    site = None
    for i, s in enumerate(sites):
        if isinstance(s, dict) and s.get("id") == site_id:
            site_idx = i
            site = s
            break
    if site is None:
        _log("NOT_FOUND", site_id_used=site_id)
        return _err("NOT_FOUND", "Site not found")
    if site.get("workspace_id") not in ws_ids:
        _log("UNAUTHORIZED", site_id_used=site_id, workspace_id_used=site.get("workspace_id"))
        return _err("UNAUTHORIZED", "Caller is not authorized to publish this site")
    if site.get("status") != "active":
        _log("INVALID_TRANSITION", site_id_used=site_id, workspace_id_used=site.get("workspace_id"))
        return _err("INVALID_TRANSITION", "Only active sites can be published")

    # Determine domains default
    if domains is None:
        doms = []
        cd = site.get("custom_domains")
        if isinstance(cd, list):
            for d in cd:
                if isinstance(d, str) and d.strip():
                    doms.append(d.strip())
        ws = site.get("webflow_subdomain")
        if isinstance(ws, str) and ws.strip():
            doms.append(ws.strip())
        domains_to_use = doms
    else:
        domains_to_use = [d.strip() for d in domains if isinstance(d, str) and d.strip()]

    if not isinstance(domains_to_use, list) or len(domains_to_use) < 1:
        _log("VALIDATION_ERROR", site_id_used=site_id, workspace_id_used=site.get("workspace_id"))
        return _err("VALIDATION_ERROR", "No publish domains available for this site")

    # Transactional behavior: build mutations then commit
    now = _now()
    pid = f"wf_pub_{int(time.time()*1000)}_{os.getpid()}_{len(publish_events)+1}"
    actor = requested_by if (isinstance(requested_by, str) and requested_by.strip()) else "ambient_caller"

    pe = {
        "id": pid,
        "site_id": site_id,
        "event_type": "site_publish",
        "collection_id": None,
        "item_ids": None,
        "domains": domains_to_use,
        "publish_mode": publish_mode,
        "requested_by": actor,
        "status": "queued",
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }

    # Simulate completion immediately (offline backend): queued->running->succeeded
    pe_running = dict(pe)
    pe_running["status"] = "running"
    pe_running["started_at"] = now
    pe_running["updated_at"] = now

    pe_done = dict(pe_running)
    pe_done["status"] = "succeeded"
    pe_done["finished_at"] = _now()
    pe_done["updated_at"] = pe_done["finished_at"]

    # Update site publish metadata
    site_new = dict(site)
    site_new["last_published_at"] = pe_done["finished_at"]
    site_new["last_published_by"] = actor
    site_new["updated_at"] = pe_done["finished_at"]

    # Commit
    publish_events.append(pe_done)
    sites[site_idx] = site_new
    _save("publish_events.json", publish_events)
    _save("sites.json", sites)

    _log("OK", site_id_used=site_id, workspace_id_used=site.get("workspace_id"))
    return {"publish_event": pe_done, "site": site_new}

def pages_list(site_id, page_type=None, status=None, collection_id=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0097000" if __import__("os").path.isdir("./environment_mix/0097000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "pages_list"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_id=None, workspace_id_used=None, site_id_used=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"wf_req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "ts": _now(),
            "endpoint": endpoint,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": credential_id,
            "workspace_id": workspace_id_used,
            "site_id": site_id_used
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    def _decode_cursor(c):
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            return obj
        except Exception:
            return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validate
    if not isinstance(site_id, str) or not re.match(r"^wf_site_[0-9A-Z]{18,}$", site_id):
        _log("VALIDATION_ERROR", site_id_used=site_id if isinstance(site_id, str) else None)
        return _err("VALIDATION_ERROR", "site_id is invalid")
    if page_type is not None:
        if not isinstance(page_type, str) or page_type not in ("static", "utility", "collection_template"):
            _log("VALIDATION_ERROR", site_id_used=site_id)
            return _err("VALIDATION_ERROR", "Invalid page_type")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted"):
            _log("VALIDATION_ERROR", site_id_used=site_id)
            return _err("VALIDATION_ERROR", "Invalid status")
    if collection_id is not None:
        if not isinstance(collection_id, str) or not re.match(r"^wf_col_[0-9A-Z]{18,}$", collection_id):
            _log("VALIDATION_ERROR", site_id_used=site_id)
            return _err("VALIDATION_ERROR", "collection_id is invalid")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("VALIDATION_ERROR", site_id_used=site_id)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")
    if cursor is not None and not isinstance(cursor, str):
        _log("VALIDATION_ERROR", site_id_used=site_id)
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if sort is None:
        sort = "path"
    if not isinstance(sort, str) or sort not in ("created_at", "updated_at", "name", "path"):
        _log("VALIDATION_ERROR", site_id_used=site_id)
        return _err("VALIDATION_ERROR", "Invalid sort field")
    if order is None:
        order = "asc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        _log("VALIDATION_ERROR", site_id_used=site_id)
        return _err("VALIDATION_ERROR", "Invalid order")

    sites = _load("sites.json")
    if not isinstance(sites, list):
        sites = []
    pages = _load("pages.json")
    if not isinstance(pages, list):
        pages = []
    collections = _load("cms_collections.json")
    if not isinstance(collections, list):
        collections = []

    site = None
    for s in sites:
        if isinstance(s, dict) and s.get("id") == site_id:
            site = s
            break
    if site is None:
        _log("NOT_FOUND", site_id_used=site_id)
        return _err("NOT_FOUND", "Site not found")

    # Tenant isolation (ambient): site.workspace_id must be in known workspaces or inferred.
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws_ids = set()
    for w in workspaces:
        if isinstance(w, dict) and isinstance(w.get("id"), str):
            ws_ids.add(w["id"])
    if not ws_ids:
        for s in sites:
            if isinstance(s, dict) and isinstance(s.get("workspace_id"), str):
                ws_ids.add(s["workspace_id"])
    if site.get("workspace_id") not in ws_ids:
        _log("UNAUTHORIZED", site_id_used=site_id, workspace_id_used=site.get("workspace_id"))
        return _err("UNAUTHORIZED", "Caller is not authorized to view pages for this site")

    # Validate collection_id reference (if provided)
    if collection_id is not None:
        col_ok = False
        for c in collections:
            if isinstance(c, dict) and c.get("id") == collection_id and c.get("site_id") == site_id:
                col_ok = True
                break
        if not col_ok:
            _log("NOT_FOUND", site_id_used=site_id, workspace_id_used=site.get("workspace_id"))
            return _err("NOT_FOUND", "Collection not found for this site")

    # Default rule: return active pages for the site, ordered by path then name.
    eff_status = status if status is not None else "active"

    filtered = []
    for p in pages:
        if not isinstance(p, dict):
            continue
        if p.get("site_id") != site_id:
            continue
        if eff_status is not None and p.get("status") != eff_status:
            continue
        if page_type is not None and p.get("page_type") != page_type:
            continue
        if collection_id is not None and p.get("collection_id") != collection_id:
            continue
        filtered.append(p)

    def _parse_dt(x):
        if x is None:
            return None
        if isinstance(x, str):
            try:
                if x.endswith("Z"):
                    return datetime.datetime.fromisoformat(x[:-1])
                return datetime.datetime.fromisoformat(x)
            except Exception:
                return None
        return None

    def _key(p):
        v = p.get(sort)
        if sort in ("created_at", "updated_at"):
            dt = _parse_dt(v)
            return (dt is None, dt or datetime.datetime.min)
        if sort in ("path", "name"):
            return (v is None, str(v).lower() if isinstance(v, str) else str(v))
        return (v is None, v)

    rev = (order == "desc")
    try:
        filtered.sort(key=_key, reverse=rev)
    except Exception:
        _log("VALIDATION_ERROR", site_id_used=site_id, workspace_id_used=site.get("workspace_id"))
        return _err("VALIDATION_ERROR", "Unable to sort with provided parameters")

    # Default secondary ordering when caller didn't override sort: path then name
    if sort == "path":
        try:
            filtered.sort(key=lambda p: ((p.get("path") is None, (p.get("path") or "").lower()),
                                         (p.get("name") is None, (p.get("name") or "").lower())),
                          reverse=rev)
        except Exception:
            pass

    offset = 0
    if cursor:
        cobj = _decode_cursor(cursor)
        if not cobj or "offset" not in cobj or not isinstance(cobj["offset"], int) or cobj["offset"] < 0:
            _log("VALIDATION_ERROR", site_id_used=site_id, workspace_id_used=site.get("workspace_id"))
