    page = copy.deepcopy(pages[idx])
    site = next((s for s in sites if isinstance(s, dict) and s.get("id") == page.get("site_id")), None)
    if site is None:
        _append_log(404, "NOT_FOUND")
        return _err("NOT_FOUND", "Page site not found", site_id=page.get("site_id"))
