            (p for p in pages
             if isinstance(p, dict)
             and p.get("site_id") == page.get("site_id")
             and p.get("status") == "active"
             and p.get("slug") == new_slug
             and p.get("id") != page.get("id")),
            None
        )
        if conflict is not None:
            _append_log(409, "CONFLICT")
            return _err("CONFLICT", "slug must be unique within the site", field="slug", site_id=page.get("site_id"))

    # Apply updates
    if name is not None:
        page["name"] = name
