        old_path = page.get("path") if isinstance(page.get("path"), str) else ""
        if old_path.startswith("/"):
            parts = old_path.split("/")
            if len(parts) <= 2:
                page["path"] = "/" + slug
            else:
                parts[-1] = slug
                page["path"] = "/".join(parts)
                if not page["path"].startswith("/"):
                    page["path"] = "/" + page["path"]
        else:
            page["path"] = "/" + slug

    if seo_title is not None:
        page["seo_title"] = seo_title
    if seo_description is not None:
        page["seo_description"] = seo_description
