    if canonical_url is not None:
        page["canonical_url"] = canonical_url
    if is_password_protected is not None:
        page["is_password_protected"] = is_password_protected

    if not isinstance(page.get("path"), str) or not page["path"].startswith("/"):
        _append_log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "path must start with '/' after slug update (business rule: path like '/%')", field="path")

    page["updated_at"] = _iso_now()

    # Persist
    pages[idx] = page
    _save("pages.json", pages)

    # Return metadata-only
    out = {}
    for k in (
        "id", "site_id", "name", "slug", "path", "page_type", "collection_id",
        "seo_title", "seo_description", "open_graph", "canonical_url",
