        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"wf_req_{int(time.time()*1000)}",
            "ts": now,
            "endpoint": "collections_list",
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential": credential,
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _decode_cursor(c):
        if c is None:
            return None
        if not isinstance(c, str) or not c:
            return None
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            return obj
        except Exception:
            return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validation
    if site_id is not None:
        if not isinstance(site_id, str):
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "site_id must be a string")
        if not re.match(r"^wf_site_[0-9A-Z]{18,}$", site_id):
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "site_id is malformed")
    if status is not None:
        if status not in ("active", "archived"):
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "status must be one of: active, archived")
    if is_singleton is not None and not isinstance(is_singleton, bool):
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "is_singleton must be a boolean")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")
    if cursor is not None and not isinstance(cursor, str):
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "updated_at", "name", "slug"):
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at, name, slug")
    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc")

    sites = _load("sites.json")
    cols = _load("cms_collections.json")
    if not isinstance(sites, list) or not isinstance(cols, list):
        _log("error", extra={"error_code": "CONFLICT"})
        return _err("CONFLICT", "Datastore is not in expected format")

    # Ambient auth: pick an accessible workspace/site combination.
    # With no explicit credential, we consider "accessible" any non-archived site.
    accessible_site_ids = {s.get("id") for s in sites if isinstance(s, dict) and s.get("status") != "archived"}
    if site_id is not None:
        # Must exist and be accessible
        site_row = next((s for s in sites if isinstance(s, dict) and s.get("id") == site_id), None)
        if site_row is None or site_row.get("status") == "archived":
            _log("error", extra={"error_code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Site not found")
        # tenant isolation (implicit): if it's accessible set contains it
        if site_id not in accessible_site_ids:
            _log("error", extra={"error_code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Site not found")
        scope_site_ids = {site_id}
    else:
        if not accessible_site_ids:
            _log("error", extra={"error_code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "No accessible sites for caller")
        scope_site_ids = accessible_site_ids

    # Apply filters
    rows = []
    for c in cols:
        if not isinstance(c, dict):
            continue
        if c.get("site_id") not in scope_site_ids:
            continue
        if status is not None and c.get("status") != status:
            continue
        # Business rule: collections_list returns active by default
        if status is None and c.get("status") != "active":
            continue
        if is_singleton is not None and c.get("is_singleton") != is_singleton:
            continue
        rows.append(c)

    # Sort
    reverse = (order == "desc")
    def _key(r):
        v = r.get(sort)
        # ISO datetimes sort lexicographically
        if v is None:
            return ""
        if isinstance(v, (str, int, float, bool)):
            return v
        return str(v)
    rows.sort(key=_key, reverse=reverse)

    # Pagination via cursor as {"offset": int, "sort": str, "order": str, "site_id": str|None, "status":..., "is_singleton":...}
    offset = 0
    if cursor:
        cur = _decode_cursor(cursor)
        if cur is None or "offset" not in cur:
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor is invalid")
        # Ensure cursor matches query shape
        if cur.get("sort") != sort or cur.get("order") != order:
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor does not match sort/order")
        if cur.get("site_id") != site_id or cur.get("status") != status or cur.get("is_singleton") != is_singleton:
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor does not match filters")
        if not isinstance(cur["offset"], int) or cur["offset"] < 0:
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor offset is invalid")
        offset = cur["offset"]

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor({"offset": next_offset, "sort": sort, "order": order, "site_id": site_id, "status": status, "is_singleton": is_singleton}) if has_more else None

    _log("ok")
    return {
        "collections": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order,
        },
    }

