def collections_items_create_item_live(collection_id, body, **_extra):
    import json, os, datetime, time, re, copy, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0097000" if __import__("os").path.isdir("./environment_mix/0097000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "collections_items_create_item_live"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _append_log(status, error_code=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append(
                {
                    "id": f"wf_req_{int(time.time()*1000)}_{len(logs)+1}",
                    "endpoint": endpoint,
                    "status": status,
                    "error_code": error_code,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "ts": _iso_now(),
                }
            )
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _enforce_limits():
        usage = _load("usage.json")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        if not isinstance(usage, dict):
            return None

        now = datetime.datetime.utcnow()
        window_s = usage.get("rate_limit_window_seconds")
        max_req = usage.get("rate_limit_max_requests")
        if isinstance(window_s, int) and window_s > 0 and isinstance(max_req, int) and max_req >= 0:
            cutoff = now - datetime.timedelta(seconds=window_s)
            recent = 0
            for r in logs:
                dt = _parse_ts(r.get("ts") or r.get("created_at"))
                if dt and dt >= cutoff:
                    recent += 1
            if recent >= max_req:
                return _err("RATE_LIMIT", "Rate limit exceeded")

        max_total = usage.get("quota_max_requests_total")
        if isinstance(max_total, int) and max_total >= 0:
            if len(logs) >= max_total:
                return _err("QUOTA_EXCEEDED", "Quota exceeded")

        return None

    def _gen_id(prefix):
        alphabet = string.ascii_uppercase + string.digits
        return prefix + "".join(random.choice(alphabet) for _ in range(22))

    def _schema_required_keys(fields_schema):
        req = []
        if not isinstance(fields_schema, list):
            return req
        for f in fields_schema:
            if not isinstance(f, dict):
                continue
            key = f.get("id") or f.get("key") or f.get("slug") or f.get("name")
            if isinstance(key, str) and key:
                if f.get("required") is True:
                    req.append(key)
        return req

    def _validate_fields_against_schema(fields, fields_schema, field_path):
        if not isinstance(fields, dict):
            return _err("VALIDATION_ERROR", "Fields must be an object", field=field_path)
        req = _schema_required_keys(fields_schema)
        missing = [k for k in req if k not in fields or fields.get(k) is None]
        if missing:
            # Note: required fields come from the schema; do not conflate with item.name/slug
            return _err(
                "VALIDATION_ERROR",
                "Missing required field(s) per collection schema: " + ", ".join(sorted(missing)),
                field=field_path,
            )
        return None

    limit_err = _enforce_limits()
    if limit_err:
        _append_log("error", limit_err["error"]["code"])
        return limit_err

    # Validate inputs
    if not isinstance(collection_id, str) or not re.match(r"^wf_col_[0-9A-Z]{18,}$", collection_id):
        e = _err("VALIDATION_ERROR", "collection_id is invalid", field="collection_id")
        _append_log("error", e["error"]["code"])
        return e
    if not isinstance(body, dict):
        e = _err("VALIDATION_ERROR", "body must be an object", field="body")
        _append_log("error", e["error"]["code"])
        return e
    for k in body.keys():
        if k not in {"name", "slug", "live_fields", "live_status", "is_archived"}:
            e = _err("VALIDATION_ERROR", f"Unknown field '{k}'", field=f"body.{k}")
            _append_log("error", e["error"]["code"])
            return e
    for reqk in ("name", "slug", "live_fields"):
        if reqk not in body:
            e = _err("VALIDATION_ERROR", f"Missing required field '{reqk}'", field=f"body.{reqk}")
            _append_log("error", e["error"]["code"])
            return e
    if not isinstance(body.get("name"), str) or not body["name"].strip():
        e = _err("VALIDATION_ERROR", "name must be a non-empty string", field="body.name")
        _append_log("error", e["error"]["code"])
        return e
    if not isinstance(body.get("slug"), str) or not body["slug"].strip():
        e = _err("VALIDATION_ERROR", "slug must be a non-empty string", field="body.slug")
        _append_log("error", e["error"]["code"])
        return e
    if body.get("live_status") is not None and body.get("live_status") not in ("unpublished", "published", "archived"):
        e = _err("VALIDATION_ERROR", "live_status is invalid", field="body.live_status")
        _append_log("error", e["error"]["code"])
        return e
    if body.get("is_archived") is not None and not isinstance(body.get("is_archived"), bool):
        e = _err("VALIDATION_ERROR", "is_archived must be boolean", field="body.is_archived")
        _append_log("error", e["error"]["code"])
        return e
    if not isinstance(body.get("live_fields"), dict):
        e = _err("VALIDATION_ERROR", "live_fields must be an object", field="body.live_fields")
        _append_log("error", e["error"]["code"])
        return e

    cols = _load("cms_collections.json")
    if not isinstance(cols, list):
        cols = []
    col = next((c for c in cols if isinstance(c, dict) and c.get("id") == collection_id), None)
    if not col:
        e = _err("NOT_FOUND", "Collection not found", collection_id=collection_id)
        _append_log("error", e["error"]["code"])
        return e
    if col.get("status") != "active":
        e = _err("INVALID_TRANSITION", "Collection is not active", collection_id=collection_id, status=col.get("status"))
        _append_log("error", e["error"]["code"])
        return e

    items = _load("cms_items.json")
    if not isinstance(items, list):
        items = []

    # Singleton enforcement
    if col.get("is_singleton") is True:
        if any(isinstance(it, dict) and it.get("collection_id") == collection_id for it in items):
            e = _err("CONFLICT", "Collection is singleton and already has an item", collection_id=collection_id)
            _append_log("error", e["error"]["code"])
            return e

    # Uniqueness on slug in collection
    new_slug = body["slug"].strip()
    if any(isinstance(it, dict) and it.get("collection_id") == collection_id and it.get("slug") == new_slug for it in items):
        e = _err("CONFLICT", "Slug already exists in collection", field="body.slug")
        _append_log("error", e["error"]["code"])
        return e

    # Validate live_fields against schema (but do not require item.name/slug inside live_fields)
    schema_err = _validate_fields_against_schema(body["live_fields"], col.get("fields_schema"), "body.live_fields")
    if schema_err:
        _append_log("error", schema_err["error"]["code"])
        return schema_err

    now = _iso_now()
    live_status = body.get("live_status") or "published"
    is_archived = body.get("is_archived")
    if is_archived is None:
        is_archived = True if live_status == "archived" else False
    # Keep consistency constraints
    if is_archived and live_status != "archived":
        e = _err("VALIDATION_ERROR", "is_archived=true requires live_status='archived'", field="body.is_archived")
        _append_log("error", e["error"]["code"])
        return e
    if live_status == "archived" and is_archived is not True:
        e = _err("VALIDATION_ERROR", "live_status='archived' requires is_archived=true", field="body.live_status")
        _append_log("error", e["error"]["code"])
        return e

    # Create item (live immediately)
    new_id = _gen_id("wf_item_")
    site_id = col.get("site_id")
    new_item = {
        "id": new_id,
        "collection_id": collection_id,
        "site_id": site_id,
        "name": body["name"].strip(),
        "slug": new_slug,
        "draft_fields": copy.deepcopy(body["live_fields"]),
        "live_fields": copy.deepcopy(body["live_fields"]),
        "draft_status": "draft",
        "live_status": live_status,
        "is_archived": bool(is_archived),
        "is_draft": False,  # created live
        "last_published_at": now if live_status == "published" else None,
        "created_at": now,
        "updated_at": now,
    }

    # Also log publish event (items_publish) for the created item (business rule)
    pubs = _load("publish_events.json")
    if not isinstance(pubs, list):
        pubs = []
    pub_id = _gen_id("wf_pub_")
    requested_by = "api"
    publish_event = {
        "id": pub_id,
        "site_id": site_id,
        "event_type": "items_publish",
        "collection_id": collection_id,
        "item_ids": [new_id],
        "domains": None,
        "publish_mode": "live",
        "requested_by": requested_by,
        "status": "succeeded",
        "error_message": None,
        "started_at": now,
        "finished_at": now,
        "created_at": now,
        "updated_at": now,
    }

    # Atomic write: append to in-memory, then save both
    try:
        items2 = items + [new_item]
        pubs2 = pubs + [publish_event]
        _save("cms_items.json", items2)
        _save("publish_events.json", pubs2)
    except Exception as ex:
        e = _err("CONFLICT", "Failed to persist item", detail=str(ex))
        _append_log("error", e["error"]["code"])
        return e

    resp = {"item": new_item, "publish_event": publish_event}
    _append_log("success", None)
    return resp

