    if not isinstance(items, list) or len(items) < 1:
        e = _err("VALIDATION_ERROR", "items must be a non-empty array", field="items")
        _append_log("error", e["error"]["code"])
        return e

    cols = _load("cms_collections.json")
    if not isinstance(cols, list):
        cols = []
    col = next((c for c in cols if isinstance(c, dict) and c.get("id") == collection_id), None)
    if not col:
        e = _err("NOT_FOUND", "Collection not found", collection_id=collection_id)
        _append_log("error", e["error"]["code"])
        return e
    if col.get("status") != "active":
        e = _err("INVALID_TRANSITION", "Collection is not active", collection_id=collection_id, status=col.get("status"))
        _append_log("error", e["error"]["code"])
        return e

    all_items = _load("cms_items.json")
    if not isinstance(all_items, list):
        all_items = []

    # Pre-validate all updates and build atomic changes
    updates = []
    seen_ids = set()
    now = _iso_now()

    for idx, upd in enumerate(items):
        pfx = f"items[{idx}]"
        if not isinstance(upd, dict):
            e = _err("VALIDATION_ERROR", "Each item update must be an object", field=pfx)
            _append_log("error", e["error"]["code"])
            return e
        for k in upd.keys():
            if k not in {"item_id", "name", "slug", "live_fields", "live_status", "is_archived"}:
                e = _err("VALIDATION_ERROR", f"Unknown field '{k}'", field=f"{pfx}.{k}")
                _append_log("error", e["error"]["code"])
                return e
        item_id = upd.get("item_id")
        if not isinstance(item_id, str) or not re.match(r"^wf_item_[0-9A-Z]{18,}$", item_id):
            e = _err("VALIDATION_ERROR", "item_id is invalid", field=f"{pfx}.item_id")
            _append_log("error", e["error"]["code"])
            return e
        if item_id in seen_ids:
            e = _err("CONFLICT", "Duplicate item_id in request", field=f"{pfx}.item_id")
            _append_log("error", e["error"]["code"])
            return e
        seen_ids.add(item_id)

        row = next((r for r in all_items if isinstance(r, dict) and r.get("id") == item_id), None)
        if not row:
            e = _err("NOT_FOUND", "Item not found", item_id=item_id)
            _append_log("error", e["error"]["code"])
            return e
        if row.get("collection_id") != collection_id:
            e = _err("NOT_FOUND", "Item does not belong to collection", item_id=item_id, collection_id=collection_id)
            _append_log("error", e["error"]["code"])
            return e

        # Must be published to update live (business rule)
        if row.get("live_status") != "published":
            e = _err("INVALID_TRANSITION", "Item must have live_status='published' for live updates", item_id=item_id)
            _append_log("error", e["error"]["code"])
            return e

        if upd.get("live_status") is not None and upd.get("live_status") not in ("unpublished", "published", "archived"):
            e = _err("VALIDATION_ERROR", "live_status is invalid", field=f"{pfx}.live_status")
            _append_log("error", e["error"]["code"])
            return e
        if upd.get("is_archived") is not None and not isinstance(upd.get("is_archived"), bool):
            e = _err("VALIDATION_ERROR", "is_archived must be boolean", field=f"{pfx}.is_archived")
            _append_log("error", e["error"]["code"])
            return e
        if upd.get("live_fields") is not None and not isinstance(upd.get("live_fields"), dict):
            e = _err("VALIDATION_ERROR", "live_fields must be an object", field=f"{pfx}.live_fields")
            _append_log("error", e["error"]["code"])
            return e

        # If slug changes, enforce uniqueness within collection (consider other updates too)
        new_slug = upd.get("slug")
        if new_slug is not None:
            if not isinstance(new_slug, str) or not new_slug.strip():
                e = _err("VALIDATION_ERROR", "slug must be a non-empty string", field=f"{pfx}.slug")
                _append_log("error", e["error"]["code"])
                return e
            new_slug = new_slug.strip()

        # Build candidate row
        cand = copy.deepcopy(row)
        if upd.get("name") is not None:
            if not isinstance(upd.get("name"), str) or not upd["name"].strip():
                e = _err("VALIDATION_ERROR", "name must be a non-empty string", field=f"{pfx}.name")
                _append_log("error", e["error"]["code"])
                return e
            cand["name"] = upd["name"].strip()
        if new_slug is not None:
            cand["slug"] = new_slug
        if upd.get("live_fields") is not None:
            # For live update, we treat it as replace of live_fields and also align draft_fields (bulk live updates affect both)
            schema_err = _validate_fields_against_schema(upd["live_fields"], col.get("fields_schema"), f"{pfx}.live_fields")
            if schema_err:
                _append_log("error", schema_err["error"]["code"])
                return schema_err
            cand["live_fields"] = copy.deepcopy(upd["live_fields"])
            cand["draft_fields"] = copy.deepcopy(upd["live_fields"])
        if upd.get("live_status") is not None:
            cand["live_status"] = upd["live_status"]
        if upd.get("is_archived") is not None:
            cand["is_archived"] = bool(upd["is_archived"])

        # Enforce is_archived consistency
        if cand.get("is_archived") is True:
            if cand.get("live_status") != "archived" or cand.get("draft_status") != "archived":
                # live update tool should not silently set draft_status; reject inconsistent request/row
                e = _err(
                    "VALIDATION_ERROR",
                    "is_archived=true requires (draft_status='archived' and live_status='archived')",
                    item_id=item_id,
                )
                _append_log("error", e["error"]["code"])
                return e

        cand["updated_at"] = now
        updates.append((row, cand))

    # Enforce slug uniqueness across resulting set
    # Start with existing slugs excluding those being updated, then apply candidates
    updated_ids = {c[1]["id"] for c in updates}
    existing_slugs = {}
    for r in all_items:
        if not isinstance(r, dict):
            continue
        if r.get("collection_id") != collection_id:
            continue
        if r.get("id") in updated_ids:
            continue
        s = r.get("slug")
        if isinstance(s, str):
            existing_slugs[s] = r.get("id")

    for _, cand in updates:
        s = cand.get("slug")
        if isinstance(s, str) and s in existing_slugs:
            e = _err("CONFLICT", "Slug already exists in collection", item_id=cand.get("id"), slug=s)
            _append_log("error", e["error"]["code"])
            return e
        if isinstance(s, str):
            existing_slugs[s] = cand.get("id")

    # Persist atomically
    try:
        new_rows = []
        cand_by_id = {cand["id"]: cand for _, cand in updates}
        for r in all_items:
            if isinstance(r, dict) and r.get("id") in cand_by_id:
                new_rows.append(cand_by_id[r["id"]])
            else:
                new_rows.append(r)
        _save("cms_items.json", new_rows)
    except Exception as ex:
        e = _err("CONFLICT", "Failed to persist updates", detail=str(ex))
        _append_log("error", e["error"]["code"])
        return e

    # Log publish event for affected items (business rule)
    pubs = _load("publish_events.json")
    if not isinstance(pubs, list):
        pubs = []
    pub_id = _gen_id("wf_pub_")
    site_id = col.get("site_id")
    event = {
        "id": pub_id,
        "site_id": site_id,
        "event_type": "items_publish",
        "collection_id": collection_id,
        "item_ids": [cand["id"] for _, cand in updates],
        "domains": None,
        "publish_mode": "live",
        "requested_by": "api",
        "status": "succeeded",
        "error_message": None,
        "started_at": now,
        "finished_at": now,
        "created_at": now,
        "updated_at": now,
    }
    try:
        _save("publish_events.json", pubs + [event])
    except Exception:
        # If publish event logging fails, treat as conflict to preserve "no success without effect" semantics
        e = _err("CONFLICT", "Failed to persist publish event")
        _append_log("error", e["error"]["code"])
        return e

    result_items = [cand for _, cand in updates]
    _append_log("success", None)
    return {"items": result_items, "publish_event": event}

def collections_items_list_items(collection_id, stage=None, status=None, is_archived=None, search=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0097000" if __import__("os").path.isdir("./environment_mix/0097000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _audit(status_code, credential_used=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"wf_req_{int(time.time()*1000)}",
            "endpoint": "collections_items_list_items",
            "credential": credential_used,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "ts": now
        })
        _save("request_logs.json", logs)

    # Basic validation
    if not isinstance(collection_id, str) or not re.match(r"^wf_col_[0-9A-Z]{18,}$", collection_id or ""):
        _audit(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "collection_id is invalid")

    if stage is None:
        stage = "draft"
    if stage not in ("draft", "live"):
        _audit(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "stage must be 'draft' or 'live'")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _audit(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")

    if sort is None:
        sort = "updated_at"
    if sort not in ("created_at", "updated_at", "name", "slug", "last_published_at"):
        _audit(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort is invalid")

    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        _audit(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "order is invalid")

    if status is not None:
        if not isinstance(status, str):
            _audit(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be a string")
        if stage == "draft" and status not in ("draft", "pending_publish", "archived"):
            _audit(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status invalid for stage=draft")
        if stage == "live" and status not in ("unpublished", "published", "archived"):
            _audit(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status invalid for stage=live")

    if is_archived is not None and not isinstance(is_archived, bool):
        _audit(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_archived must be boolean")

    if search is not None and not isinstance(search, str):
        _audit(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "search must be a string")

    # Cursor decode
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _audit(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or obj.get("v") != 1 or obj.get("collection_id") != collection_id:
                _audit(400, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor is invalid for this collection")
            offset = int(obj.get("offset", 0))
            if offset < 0:
                raise ValueError("bad offset")
        except Exception:
            _audit(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid")

    # Foreign key: collection exists (and site exists)
    cols = _load("cms_collections.json")
    if not isinstance(cols, list):
        cols = []
    col = next((c for c in cols if isinstance(c, dict) and c.get("id") == collection_id), None)
    if not col:
        _audit(404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Collection not found", collection_id=collection_id)

    sites = _load("sites.json")
    if not isinstance(sites, list):
        sites = []
    site = next((s for s in sites if isinstance(s, dict) and s.get("id") == col.get("site_id")), None)
    if not site:
        _audit(404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Owning site not found for collection", site_id=col.get("site_id"))

    items = _load("cms_items.json")
    if not isinstance(items, list):
        items = []

    # Filtering
    res = []
    term = (search or "").strip().lower()
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("collection_id") != collection_id:
            continue
        # Integrity: site_id must match collection.site_id; skip inconsistent rows
        if it.get("site_id") != col.get("site_id"):
            continue

        # Archived exclusion default: exclude archived unless explicitly requested (internal flag not exposed)
        # We interpret "explicitly requested" as is_archived filter provided or status='archived'
        if is_archived is None and status != "archived":
            if it.get("is_archived") is True or it.get("draft_status") == "archived" or it.get("live_status") == "archived":
                continue

        if is_archived is not None and bool(it.get("is_archived")) != is_archived:
            continue

        if status is not None:
            if stage == "draft":
                if it.get("draft_status") != status:
                    continue
            else:
                if it.get("live_status") != status:
                    continue

        if term:
            nm = (it.get("name") or "").lower()
            sl = (it.get("slug") or "").lower()
            if term not in nm and term not in sl:
                continue

        res.append(it)

    def _dt_key(v):
        if v is None:
            return ""
        if isinstance(v, str):
            return v
        return str(v)

    def _sort_key(it):
        val = it.get(sort)
        if sort in ("created_at", "updated_at", "last_published_at"):
            return _dt_key(val), (it.get("id") or "")
        else:
            return (val or ""), (it.get("id") or "")

    reverse = (order == "desc")
    res.sort(key=_sort_key, reverse=reverse)

    total = len(res)
    page = res[offset: offset + limit]
    next_cursor = None
    if offset + limit < total:
        payload = {"v": 1, "collection_id": collection_id, "offset": offset + limit}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8")

    # Stage shaping: do not fabricate; return stored rows. (Vendor often returns stage-specific; here we include all fields.)
    _audit(200)
    return {
        "items": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "has_more": (next_cursor is not None),
            "next_cursor": next_cursor
        }
    }

def collections_items_create_item(collection_id, body, **_extra):
    import json, os, datetime, time, re, copy, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0097000" if __import__("os").path.isdir("./environment_mix/0097000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "collections_items_create_item"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _append_log(status, error_code=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append(
                {
                    "id": f"wf_req_{int(time.time()*1000)}_{len(logs)+1}",
                    "endpoint": endpoint,
                    "status": status,
                    "error_code": error_code,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "ts": _iso_now(),
                }
            )
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _enforce_limits():
        usage = _load("usage.json")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        if not isinstance(usage, dict):
            return None
        now = datetime.datetime.utcnow()
        window_s = usage.get("rate_limit_window_seconds")
        max_req = usage.get("rate_limit_max_requests")
        if isinstance(window_s, int) and window_s > 0 and isinstance(max_req, int) and max_req >= 0:
            cutoff = now - datetime.timedelta(seconds=window_s)
            recent = 0
            for r in logs:
                dt = _parse_ts(r.get("ts") or r.get("created_at"))
                if dt and dt >= cutoff:
                    recent += 1
            if recent >= max_req:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        max_total = usage.get("quota_max_requests_total")
        if isinstance(max_total, int) and max_total >= 0:
            if len(logs) >= max_total:
                return _err("QUOTA_EXCEEDED", "Quota exceeded")
        return None

    def _gen_id(prefix):
        alphabet = string.ascii_uppercase + string.digits
        return prefix + "".join(random.choice(alphabet) for _ in range(22))

    def _schema_required_keys(fields_schema):
        req = []
        if not isinstance(fields_schema, list):
            return req
        for f in fields_schema:
            if not isinstance(f, dict):
                continue
            key = f.get("id") or f.get("key") or f.get("slug") or f.get("name")
            if isinstance(key, str) and key and f.get("required") is True:
                req.append(key)
        return req

    def _validate_fields_against_schema(fields, fields_schema, field_path):
        if not isinstance(fields, dict):
            return _err("VALIDATION_ERROR", "Fields must be an object", field=field_path)
        req = _schema_required_keys(fields_schema)
        missing = [k for k in req if k not in fields or fields.get(k) is None]
        if missing:
            return _err(
                "VALIDATION_ERROR",
                "Missing required field(s) per collection schema: " + ", ".join(sorted(missing)),
                field=field_path,
            )
        return None

    limit_err = _enforce_limits()
    if limit_err:
        _append_log("error", limit_err["error"]["code"])
        return limit_err

    if not isinstance(collection_id, str) or not re.match(r"^wf_col_[0-9A-Z]{18,}$", collection_id):
        e = _err("VALIDATION_ERROR", "collection_id is invalid", field="collection_id")
        _append_log("error", e["error"]["code"])
        return e
    if not isinstance(body, dict):
        e = _err("VALIDATION_ERROR", "body must be an object", field="body")
        _append_log("error", e["error"]["code"])
        return e
    for k in body.keys():
        if k not in {"name", "slug", "draft_fields", "draft_status", "is_archived", "is_draft"}:
            e = _err("VALIDATION_ERROR", f"Unknown field '{k}'", field=f"body.{k}")
            _append_log("error", e["error"]["code"])
            return e
    for reqk in ("name", "slug", "draft_fields"):
        if reqk not in body:
            e = _err("VALIDATION_ERROR", f"Missing required field '{reqk}'", field=f"body.{reqk}")
            _append_log("error", e["error"]["code"])
            return e
    if not isinstance(body.get("name"), str) or not body["name"].strip():
        e = _err("VALIDATION_ERROR", "name must be a non-empty string", field="body.name")
        _append_log("error", e["error"]["code"])
        return e
    if not isinstance(body.get("slug"), str) or not body["slug"].strip():
        e = _err("VALIDATION_ERROR", "slug must be a non-empty string", field="body.slug")
        _append_log("error", e["error"]["code"])
        return e
    if not isinstance(body.get("draft_fields"), dict):
        e = _err("VALIDATION_ERROR", "draft_fields must be an object", field="body.draft_fields")
        _append_log("error", e["error"]["code"])
        return e
    if body.get("draft_status") is not None and body.get("draft_status") not in ("draft", "pending_publish", "archived"):
        e = _err("VALIDATION_ERROR", "draft_status is invalid", field="body.draft_status")
        _append_log("error", e["error"]["code"])
        return e
    if body.get("is_archived") is not None and not isinstance(body.get("is_archived"), bool):
        e = _err("VALIDATION_ERROR", "is_archived must be boolean", field="body.is_archived")
        _append_log("error", e["error"]["code"])
        return e
    if body.get("is_draft") is not None and not isinstance(body.get("is_draft"), bool):
        e = _err("VALIDATION_ERROR", "is_draft must be boolean", field="body.is_draft")
        _append_log("error", e["error"]["code"])
        return e

    cols = _load("cms_collections.json")
    if not isinstance(cols, list):
        cols = []
    col = next((c for c in cols if isinstance(c, dict) and c.get("id") == collection_id), None)
    if not col:
        e = _err("NOT_FOUND", "Collection not found", collection_id=collection_id)
        _append_log("error", e["error"]["code"])
        return e
    if col.get("status") != "active":
        e = _err("INVALID_TRANSITION", "Collection is not active", collection_id=collection_id, status=col.get("status"))
        _append_log("error", e["error"]["code"])
        return e

    all_items = _load("cms_items.json")
    if not isinstance(all_items, list):
        all_items = []

    # Singleton enforcement
    if col.get("is_singleton") is True:
        if any(isinstance(it, dict) and it.get("collection_id") == collection_id for it in all_items):
            e = _err("CONFLICT", "Collection is singleton and already has an item", collection_id=collection_id)
            _append_log("error", e["error"]["code"])
            return e

    slug = body["slug"].strip()
    if any(isinstance(it, dict) and it.get("collection_id") == collection_id and it.get("slug") == slug for it in all_items):
        e = _err("CONFLICT", "Slug already exists in collection", field="body.slug")
        _append_log("error", e["error"]["code"])
        return e

    schema_err = _validate_fields_against_schema(body["draft_fields"], col.get("fields_schema"), "body.draft_fields")
    if schema_err:
        _append_log("error", schema_err["error"]["code"])
        return schema_err

    now = _iso_now()
    draft_status = body.get("draft_status") or "draft"
    is_archived = body.get("is_archived")
    if is_archived is None:
        is_archived = True if draft_status == "archived" else False

    # Derived flags / statuses
    live_status = "unpublished"
    is_draft_flag = body.get("is_draft")
    if is_draft_flag is None:
        is_draft_flag = True  # business rule: created draft item => is_draft true

    # Consistency
    if is_archived and draft_status != "archived":
        e = _err("VALIDATION_ERROR", "is_archived=true requires draft_status='archived'", field="body.is_archived")
        _append_log("error", e["error"]["code"])
        return e
    if draft_status == "archived" and is_archived is not True:
        e = _err("VALIDATION_ERROR", "draft_status='archived' requires is_archived=true", field="body.draft_status")
        _append_log("error", e["error"]["code"])
        return e
    if is_draft_flag is True and live_status != "unpublished":
        e = _err("VALIDATION_ERROR", "is_draft=true implies live_status='unpublished'", field="body.is_draft")
        _append_log("error", e["error"]["code"])
        return e

    new_id = _gen_id("wf_item_")
    new_row = {
        "id": new_id,
        "collection_id": collection_id,
        "site_id": col.get("site_id"),
        "name": body["name"].strip(),
        "slug": slug,
        "draft_fields": copy.deepcopy(body["draft_fields"]),
        "live_fields": None,
        "draft_status": draft_status,
        "live_status": live_status if not is_archived else "archived",
        "is_archived": bool(is_archived),
        "is_draft": bool(is_draft_flag),
        "last_published_at": None,
        "created_at": now,
        "updated_at": now,
    }

    # Enforce: is_archived => both statuses archived
    if new_row["is_archived"]:
        if not (new_row["draft_status"] == "archived" and new_row["live_status"] == "archived"):
            e = _err(
                "VALIDATION_ERROR",
                "is_archived=true implies (draft_status='archived' and live_status='archived')",
                item_id=new_id,
            )
            _append_log("error", e["error"]["code"])
            return e

    try:
        _save("cms_items.json", all_items + [new_row])
    except Exception as ex:
        e = _err("CONFLICT", "Failed to persist item", detail=str(ex))
        _append_log("error", e["error"]["code"])
        return e

    _append_log("success", None)
    return {"item": new_row}

def collections_items_update_items(collection_id, items, **_extra):
    import json, os, datetime, time, re, copy
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0097000" if __import__("os").path.isdir("./environment_mix/0097000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "collections_items_update_items"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _append_log(status, error_code=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append(
                {
                    "id": f"wf_req_{int(time.time()*1000)}_{len(logs)+1}",
                    "endpoint": endpoint,
                    "status": status,
                    "error_code": error_code,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "ts": _iso_now(),
                }
            )
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _enforce_limits():
        usage = _load("usage.json")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        if not isinstance(usage, dict):
            return None
        now = datetime.datetime.utcnow()
        window_s = usage.get("rate_limit_window_seconds")
        max_req = usage.get("rate_limit_max_requests")
        if isinstance(window_s, int) and window_s > 0 and isinstance(max_req, int) and max_req >= 0:
            cutoff = now - datetime.timedelta(seconds=window_s)
            recent = 0
            for r in logs:
                dt = _parse_ts(r.get("ts") or r.get("created_at"))
                if dt and dt >= cutoff:
                    recent += 1
            if recent >= max_req:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        max_total = usage.get("quota_max_requests_total")
        if isinstance(max_total, int) and max_total >= 0:
            if len(logs) >= max_total:
                return _err("QUOTA_EXCEEDED", "Quota exceeded")
        return None

    def _schema_required_keys(fields_schema):
        req = []
        if not isinstance(fields_schema, list):
            return req
        for f in fields_schema:
            if not isinstance(f, dict):
                continue
            key = f.get("id") or f.get("key") or f.get("slug") or f.get("name")
            if isinstance(key, str) and key and f.get("required") is True:
                req.append(key)
        return req

    def _validate_fields_against_schema(fields, fields_schema, field_path):
        if fields is None:
            return None
        if not isinstance(fields, dict):
            return _err("VALIDATION_ERROR", "Fields must be an object", field=field_path)
        req = _schema_required_keys(fields_schema)
        missing = [k for k in req if k not in fields or fields.get(k) is None]
        if missing:
            return _err(
                "VALIDATION_ERROR",
                "Missing required field(s) per collection schema: " + ", ".join(sorted(missing)),
                field=field_path,
            )
        return None

    limit_err = _enforce_limits()
    if limit_err:
        _append_log("error", limit_err["error"]["code"])
        return limit_err

    if not isinstance(collection_id, str) or not re.match(r"^wf_col_[0-9A-Z]{18,}$", collection_id):
        e = _err("VALIDATION_ERROR", "collection_id is invalid", field="collection_id")
        _append_log("error", e["error"]["code"])
        return e
    if not isinstance(items, list) or len(items) < 1:
        e = _err("VALIDATION_ERROR", "items must be a non-empty array", field="items")
        _append_log("error", e["error"]["code"])
        return e

    cols = _load("cms_collections.json")
    if not isinstance(cols, list):
        cols = []
    col = next((c for c in cols if isinstance(c, dict) and c.get("id") == collection_id), None)
    if not col:
        e = _err("NOT_FOUND", "Collection not found", collection_id=collection_id)
        _append_log("error", e["error"]["code"])
        return e
    if col.get("status") != "active":
        e = _err("INVALID_TRANSITION", "Collection is not active", collection_id=collection_id, status=col.get("status"))
        _append_log("error", e["error"]["code"])
        return e

    all_items = _load("cms_items.json")
    if not isinstance(all_items, list):
        all_items = []

    now = _iso_now()
    updates = []
    seen_ids = set()

    for idx, upd in enumerate(items):
        pfx = f"items[{idx}]"
        if not isinstance(upd, dict):
            e = _err("VALIDATION_ERROR", "Each item update must be an object", field=pfx)
            _append_log("error", e["error"]["code"])
            return e
        for k in upd.keys():
            if k not in {"item_id", "name", "slug", "draft_fields", "draft_status", "is_archived", "is_draft"}:
                e = _err("VALIDATION_ERROR", f"Unknown field '{k}'", field=f"{pfx}.{k}")
                _append_log("error", e["error"]["code"])
                return e

        item_id = upd.get("item_id")
        if not isinstance(item_id, str) or not re.match(r"^wf_item_[0-9A-Z]{18,}$", item_id):
            e = _err("VALIDATION_ERROR", "item_id is invalid", field=f"{pfx}.item_id")
            _append_log("error", e["error"]["code"])
            return e
        if item_id in seen_ids:
            e = _err("CONFLICT", "Duplicate item_id in request", field=f"{pfx}.item_id")
            _append_log("error", e["error"]["code"])
            return e
        seen_ids.add(item_id)

        row = next((r for r in all_items if isinstance(r, dict) and r.get("id") == item_id), None)
        if not row:
            e = _err("NOT_FOUND", "Item not found", item_id=item_id)
            _append_log("error", e["error"]["code"])
            return e
        if row.get("collection_id") != collection_id:
            e = _err("NOT_FOUND", "Item does not belong to collection", item_id=item_id, collection_id=collection_id)
            _append_log("error", e["error"]["code"])
            return e

        # Business rule: archived draft items must be rejected for updates
        if row.get("draft_status") == "archived":
            e = _err("INVALID_TRANSITION", "Archived items cannot be updated", item_id=item_id)
            _append_log("error", e["error"]["code"])
            return e

        if upd.get("draft_status") is not None and upd.get("draft_status") not in ("draft", "pending_publish", "archived"):
            e = _err("VALIDATION_ERROR", "draft_status is invalid", field=f"{pfx}.draft_status")
            _append_log("error", e["error"]["code"])
            return e
        if upd.get("is_archived") is not None and not isinstance(upd.get("is_archived"), bool):
            e = _err("VALIDATION_ERROR", "is_archived must be boolean", field=f"{pfx}.is_archived")
            _append_log("error", e["error"]["code"])
            return e
        if upd.get("is_draft") is not None and not isinstance(upd.get("is_draft"), bool):
            e = _err("VALIDATION_ERROR", "is_draft must be boolean", field=f"{pfx}.is_draft")
            _append_log("error", e["error"]["code"])
            return e
        if upd.get("draft_fields") is not None and not isinstance(upd.get("draft_fields"), dict):
            e = _err("VALIDATION_ERROR", "draft_fields must be an object", field=f"{pfx}.draft_fields")
            _append_log("error", e["error"]["code"])
            return e

        new_slug = upd.get("slug")
        if new_slug is not None:
            if not isinstance(new_slug, str) or not new_slug.strip():
                e = _err("VALIDATION_ERROR", "slug must be a non-empty string", field=f"{pfx}.slug")
                _append_log("error", e["error"]["code"])
                return e
            new_slug = new_slug.strip()

        cand = copy.deepcopy(row)
        if upd.get("name") is not None:
            if not isinstance(upd.get("name"), str) or not upd["name"].strip():
                e = _err("VALIDATION_ERROR", "name must be a non-empty string", field=f"{pfx}.name")
                _append_log("error", e["error"]["code"])
                return e
            cand["name"] = upd["name"].strip()
        if new_slug is not None:
            cand["slug"] = new_slug
        if upd.get("draft_fields") is not None:
            schema_err = _validate_fields_against_schema(upd["draft_fields"], col.get("fields_schema"), f"{pfx}.draft_fields")
            if schema_err:
                _append_log("error", schema_err["error"]["code"])
                return schema_err
            cand["draft_fields"] = copy.deepcopy(upd["draft_fields"])
        if upd.get("draft_status") is not None:
            # enforce lifecycle transitions
            curr = row.get("draft_status")
            nxt = upd["draft_status"]
            allowed = {"draft": {"pending_publish", "archived"}, "pending_publish": {"draft", "archived"}, "archived": set()}
            if curr not in allowed or nxt not in allowed.get(curr, set()):
                e = _err("INVALID_TRANSITION", f"Illegal draft_status transition {curr!r} -> {nxt!r}", item_id=item_id)
                _append_log("error", e["error"]["code"])
                return e
            cand["draft_status"] = nxt
        if upd.get("is_archived") is not None:
            cand["is_archived"] = bool(upd["is_archived"])
        if upd.get("is_draft") is not None:
            cand["is_draft"] = bool(upd["is_draft"])

        # Consistency constraints
        if cand.get("is_archived") is True:
            if not (cand.get("draft_status") == "archived" and cand.get("live_status") == "archived"):
                e = _err(
                    "VALIDATION_ERROR",
                    "is_archived=true implies (draft_status='archived' and live_status='archived')",
                    item_id=item_id,
                )
                _append_log("error", e["error"]["code"])
                return e
        if cand.get("is_draft") is True and cand.get("live_status") != "unpublished":
            e = _err("VALIDATION_ERROR", "is_draft=true implies live_status='unpublished'", item_id=item_id)
            _append_log("error", e["error"]["code"])
            return e

        cand["updated_at"] = now
        updates.append((row, cand))

    # Enforce slug uniqueness across resulting set
    updated_ids = {cand["id"] for _, cand in updates}
    slugs = {}
    for r in all_items:
        if not isinstance(r, dict):
            continue
        if r.get("collection_id") != collection_id:
            continue
        if r.get("id") in updated_ids:
            continue
        s = r.get("slug")
        if isinstance(s, str):
            slugs[s] = r.get("id")

    for _, cand in updates:
        s = cand.get("slug")
        if isinstance(s, str) and s in slugs and slugs[s] != cand.get("id"):
            e = _err("CONFLICT", "Slug already exists in collection", item_id=cand.get("id"), slug=s)
            _append_log("error", e["error"]["code"])
            return e
        if isinstance(s, str):
            slugs[s] = cand.get("id")

    # Persist atomically
    try:
        cand_by_id = {cand["id"]: cand for _, cand in updates}
        new_rows = []
        for r in all_items:
            if isinstance(r, dict) and r.get("id") in cand_by_id:
                new_rows.append(cand_by_id[r["id"]])
            else:
                new_rows.append(r)
        _save("cms_items.json", new_rows)
    except Exception as ex:
        e = _err("CONFLICT", "Failed to persist updates", detail=str(ex))
        _append_log("error", e["error"]["code"])
        return e

    result_items = [cand for _, cand in updates]
    _append_log("success", None)
    return {"items": result_items}

def collections_items_publish_items(collection_id, item_ids, publish_mode=None, requested_by=None, **_extra):
    import json, os, datetime, time, re, copy, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0097000" if __import__("os").path.isdir("./environment_mix/0097000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "collections_items_publish_items"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _append_log(status, error_code=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append(
                {
                    "id": f"wf_req_{int(time.time()*1000)}_{len(logs)+1}",
                    "endpoint": endpoint,
                    "status": status,
                    "error_code": error_code,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "ts": _iso_now(),
                }
            )
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _enforce_limits():
        usage = _load("usage.json")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        if not isinstance(usage, dict):
            return None
        now = datetime.datetime.utcnow()
        window_s = usage.get("rate_limit_window_seconds")
        max_req = usage.get("rate_limit_max_requests")
        if isinstance(window_s, int) and window_s > 0 and isinstance(max_req, int) and max_req >= 0:
            cutoff = now - datetime.timedelta(seconds=window_s)
            recent = 0
            for r in logs:
                dt = _parse_ts(r.get("ts") or r.get("created_at"))
                if dt and dt >= cutoff:
                    recent += 1
            if recent >= max_req:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        max_total = usage.get("quota_max_requests_total")
        if isinstance(max_total, int) and max_total >= 0:
            if len(logs) >= max_total:
                return _err("QUOTA_EXCEEDED", "Quota exceeded")
        return None

    def _gen_id(prefix):
        alphabet = string.ascii_uppercase + string.digits
        return prefix + "".join(random.choice(alphabet) for _ in range(22))

    limit_err = _enforce_limits()
    if limit_err:
        _append_log("error", limit_err["error"]["code"])
        return limit_err

    if not isinstance(collection_id, str) or not re.match(r"^wf_col_[0-9A-Z]{18,}$", collection_id):
        e = _err("VALIDATION_ERROR", "collection_id is invalid", field="collection_id")
        _append_log("error", e["error"]["code"])
        return e
    if not isinstance(item_ids, list) or len(item_ids) < 1:
        e = _err("VALIDATION_ERROR", "item_ids must be a non-empty array", field="item_ids")
        _append_log("error", e["error"]["code"])
        return e
    for i, iid in enumerate(item_ids):
        if not isinstance(iid, str) or not re.match(r"^wf_item_[0-9A-Z]{18,}$", iid):
            e = _err("VALIDATION_ERROR", "item_id is invalid", field=f"item_ids[{i}]")
            _append_log("error", e["error"]["code"])
            return e
    if publish_mode is not None and publish_mode not in ("live", "staging"):
        e = _err("VALIDATION_ERROR", "publish_mode is invalid", field="publish_mode")
        _append_log("error", e["error"]["code"])
        return e
    if requested_by is not None and not isinstance(requested_by, str):
        e = _err("VALIDATION_ERROR", "requested_by must be a string", field="requested_by")
        _append_log("error", e["error"]["code"])
        return e

    cols = _load("cms_collections.json")
    if not isinstance(cols, list):
        cols = []
    col = next((c for c in cols if isinstance(c, dict) and c.get("id") == collection_id), None)
    if not col:
        e = _err("NOT_FOUND", "Collection not found", collection_id=collection_id)
        _append_log("error", e["error"]["code"])
        return e
    if col.get("status") != "active":
        e = _err("INVALID_TRANSITION", "Collection is not active", collection_id=collection_id, status=col.get("status"))
        _append_log("error", e["error"]["code"])
        return e

    all_items = _load("cms_items.json")
    if not isinstance(all_items, list):
        all_items = []

    # Verify all items exist and belong to collection
    target_rows = []
    seen = set()
    for iid in item_ids:
        if iid in seen:
            continue
        seen.add(iid)
        row = next((r for r in all_items if isinstance(r, dict) and r.get("id") == iid), None)
        if not row:
            e = _err("NOT_FOUND", "Item not found", item_id=iid)
            _append_log("error", e["error"]["code"])
            return e
        if row.get("collection_id") != collection_id:
            e = _err("NOT_FOUND", "Item does not belong to collection", item_id=iid, collection_id=collection_id)
            _append_log("error", e["error"]["code"])
            return e
        # Archived items cannot be published (consistent with lifecycle)
        if row.get("draft_status") == "archived" or row.get("live_status") == "archived" or row.get("is_archived") is True:
            e = _err("INVALID_TRANSITION", "Archived items cannot be published", item_id=iid)
            _append_log("error", e["error"]["code"])
            return e
        target_rows.append(row)

    mode = publish_mode or "live"
    actor = requested_by or "api"
    now = _iso_now()

    # Create publish event queued then immediately succeed (synchronous simulation)
    pubs = _load("publish_events.json")
    if not isinstance(pubs, list):
        pubs = []
    pub_id = _gen_id("wf_pub_")
    event = {
        "id": pub_id,
        "site_id": col.get("site_id"),
        "event_type": "items_publish",
        "collection_id": collection_id,
        "item_ids": [r.get("id") for r in target_rows],
        "domains": None,
        "publish_mode": mode,
        "requested_by": actor,
        "status": "queued",
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }

    # Apply publish (atomic): set live_fields=draft_fields, statuses, timestamps
    updated_by_id = {}
    started = now
    finished = now
    for r in target_rows:
        cand = copy.deepcopy(r)
        cand["live_fields"] = copy.deepcopy(r.get("draft_fields"))
        cand["live_status"] = "published"
        cand["is_draft"] = False
        cand["draft_status"] = "draft"
        cand["last_published_at"] = now
        cand["updated_at"] = now
        updated_by_id[cand["id"]] = cand

    event2 = copy.deepcopy(event)
    event2["status"] = "succeeded"
    event2["started_at"] = started
    event2["finished_at"] = finished
    event2["updated_at"] = now

    try:
        new_items = []
        for r in all_items:
            if isinstance(r, dict) and r.get("id") in updated_by_id:
                new_items.append(updated_by_id[r["id"]])
            else:
                new_items.append(r)
        _save("cms_items.json", new_items)
        _save("publish_events.json", pubs + [event2])
    except Exception as ex:
        e = _err("CONFLICT", "Failed to persist publish", detail=str(ex))
        _append_log("error", e["error"]["code"])
        return e

    _append_log("success", None)
    return {"publish_event": event2, "items": [updated_by_id[r["id"]] for r in target_rows]}

