        if not isinstance(logs, list):
            logs = []
        window_s = usage.get("rate_limit_window_seconds")
        max_req = usage.get("rate_limit_max_requests")
        if isinstance(window_s, int) and window_s > 0 and isinstance(max_req, int) and max_req >= 0:
            cutoff = now - datetime.timedelta(seconds=window_s)
            recent = 0
            for r in logs:
                ts = r.get("ts") or r.get("created_at")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts[:-1]) if ts.endswith("Z") else datetime.datetime.fromisoformat(ts)
                except Exception:
                    continue
                if dt >= cutoff:
                    recent += 1
            if recent >= max_req:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        max_total = usage.get("quota_max_requests_total")
        if isinstance(max_total, int) and max_total >= 0:
            if len(logs) >= max_total:
                return _err("QUOTA_EXCEEDED", "Quota exceeded")
        return None

    lim = _enforce_limits()
    if lim:
        _append_log(429, lim["error"]["code"])
        return lim

    if not isinstance(site_id, str) or not re.match(r"^wf_site_[0-9A-Z]{18,}$", site_id or ""):
        _append_log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "site_id is invalid", field="site_id")

    if name is not None and (not isinstance(name, str) or not (1 <= len(name) <= 200)):
        _append_log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must be a non-empty string up to 200 chars", field="name")
    if short_name is not None and (not isinstance(short_name, str) or not (1 <= len(short_name) <= 100)):
        _append_log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "short_name must be a non-empty string up to 100 chars", field="short_name")
    if timezone is not None and (not isinstance(timezone, str) or not (1 <= len(timezone) <= 64)):
        _append_log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "timezone must be a non-empty string up to 64 chars", field="timezone")
    if custom_domains is not None:
        if not isinstance(custom_domains, list):
            _append_log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "custom_domains must be an array of strings", field="custom_domains")
        for d in custom_domains:
            if not isinstance(d, str) or not d.strip() or len(d) > 253:
                _append_log(400, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "custom_domains must be array of non-empty domain strings (<=253 chars)", field="custom_domains")
            # basic domain format validation
            dom = d.strip().lower()
            if "://" in dom or "/" in dom or " " in dom or dom.startswith(".") or dom.endswith(".") or ".." in dom:
                _append_log(400, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "custom_domains contains malformed domain name (business rule)", field="custom_domains", domain=d)

    if status is not None and status not in ("active", "disabled"):
        _append_log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be 'active' or 'disabled'", field="status")

    sites = _load("sites.json")
    if isinstance(sites, dict) and "rows" in sites:
        sites = sites.get("rows")
    if not isinstance(sites, list):
        sites = []

    idx = next((i for i, s in enumerate(sites) if isinstance(s, dict) and s.get("id") == site_id), None)
    if idx is None:
        _append_log(404, "NOT_FOUND")
        return _err("NOT_FOUND", "Site not found", site_id=site_id)

    site = copy.deepcopy(sites[idx])
    if site.get("status") == "archived":
        _append_log(404, "NOT_FOUND")
        return _err("NOT_FOUND", "Site not accessible", reason="archived")

    # Enforce unique(workspace_id, name) if name is changing
    if name is not None and name != site.get("name"):
        ws = site.get("workspace_id")
        if next((s for s in sites if isinstance(s, dict) and s.get("workspace_id") == ws and s.get("name") == name and s.get("id") != site_id), None) is not None:
            _append_log(409, "CONFLICT")
            return _err("CONFLICT", "Site name must be unique within workspace", field="name", workspace_id=ws)

    # Status transitions: only active <-> disabled; forbid archived via this endpoint
    if status is not None:
        if status == "archived":
            _append_log(409, "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Refuses attempts to set status to archived through this endpoint (business rule)")
        if site.get("status") != status:
            transitions = {"active": {"disabled"}, "disabled": {"active"}, "archived": set()}
            cur = site.get("status")
            if cur not in transitions or status not in transitions[cur]:
                _append_log(409, "INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", "Illegal site status transition (business rule)", from_status=cur, to_status=status)
            site["status"] = status

    if name is not None:
        site["name"] = name
    if short_name is not None:
        site["short_name"] = short_name
    if timezone is not None:
        site["timezone"] = timezone
    if custom_domains is not None:
        site["custom_domains"] = list(custom_domains)

    site["updated_at"] = _iso_now()
    sites[idx] = site
    _save("sites.json", sites)

    _append_log(200, None)
    return {"site": site}
